def fib(n, memo=None):
    if memo is None:
        memo = {}
    if n < 0:
        raise ValueError("Input must be non-negative")
    if n in memo:
        return memo[n]
    if n <= 1:
        memo[n] = n
    else:
        memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]
